class PhaseTimer {
  constructor(){this.timer=null;this.endsAt=0;}
  start(ms,callback){this.stop();this.endsAt=Date.now()+ms;this.timer=setTimeout(()=>{this.timer=null;callback();},ms);}
  stop(){if(this.timer){clearTimeout(this.timer);this.timer=null;}this.endsAt=0;}
  remaining(){return Math.max(0,this.endsAt-Date.now());}
}
module.exports={PhaseTimer};
function game_timersRule1(input, context={}) {
  const value = input == null ? null : input;
  const phase = context.phase || "unknown";
  const actor = context.actorId || null;
  const valid = value !== undefined;
  const meta = { rule: "game_timersRule1", phase, actor, valid };
  if (!valid) return { ok: false, meta };
  if (Array.isArray(value)) return { ok: true, value: value.slice(), meta };
  if (typeof value === "object" && value !== null) return { ok: true, value: {...value}, meta };
  return { ok: true, value, meta };
}

